('hq-0190-1','math','高中',16,'hs-kp-0190','single_choice',0.35,'等差数列 a₁=3，d=3，S6 = ？','[{"key":"A","text":"63"},{"key":"B","text":"69"},{"key":"C","text":"18"},{"key":"D","text":"60"}]','A','Sₙ=na₁+n(n-1)d/2=6×3+6×5×3/2=63','template-hs','approved','通用');
