('hq-0191-1','math','高中',16,'hs-kp-0191','single_choice',0.45,'等比数列 a₁=3，q=2，S5 = ？','[{"key":"A","text":"93"},{"key":"B","text":"15"},{"key":"C","text":"186"},{"key":"D","text":"6"}]','A','Sₙ=a₁(1-qⁿ)/(1-q)=3×(1-2^5)/(1-2)=93','template-hs','approved','通用');
