('hq-0198-1','math','高中',16,'hs-kp-0198','single_choice',0.65,'aₙ/aₙ₋₁=n/(n-1)，a₁=1，则 a3 = ？','[{"key":"A","text":"3"},{"key":"B","text":"2"},{"key":"C","text":"9"},{"key":"D","text":"1"}]','A','累乘法：aₙ=a₁×2/1×3/2×...×n/(n-1)=3','template-hs','approved','通用');